import { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

const vertexShader = `
  uniform float uTime;
  attribute float aSize;
  attribute float aDepth;
  varying float vDepth;
  varying float vAlpha;

  void main() {
    vDepth = aDepth;

    // Pulse each particle size using time and its Z position
    float pulse = 1.0 + 0.4 * sin(uTime * 2.0 + position.z * 0.04 + aDepth * 6.28);
    float finalSize = aSize * pulse;

    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = finalSize * (280.0 / -mvPosition.z);
    gl_Position = projectionMatrix * mvPosition;

    vAlpha = 0.5 + 0.5 * sin(uTime * 1.5 + position.z * 0.08);
  }
`;

const fragmentShader = `
  varying float vDepth;
  varying float vAlpha;

  void main() {
    float dist = length(gl_PointCoord - vec2(0.5));
    float alpha = 1.0 - smoothstep(0.2, 0.5, dist);

    // Mix between white and the --accent color (#818cf8 -> RGB: 129, 140, 248)
    vec3 colorNear = vec3(1.0, 1.0, 1.0); // pure white
    vec3 colorFar  = vec3(0.506, 0.549, 0.973); // #818cf8
    vec3 color  = mix(colorNear, colorFar, vDepth);

    gl_FragColor = vec4(color, alpha * vAlpha * 0.8);
  }
`;

export default function ParticleTunnel({ count = 1500 }) {
  const meshRef  = useRef();
  const matRef   = useRef();
  const timeRef  = useRef(0);
  const depth    = 280;

  const { positions, sizes, depths } = useMemo(() => {
    const positions = new Float32Array(count * 3);
    const sizes     = new Float32Array(count);
    const depths    = new Float32Array(count);

    for (let i = 0; i < count; i++) {
      const radius = 2 + Math.random() * 16;
      const angle  = Math.random() * Math.PI * 2;
      const z      = (Math.random() - 0.5) * depth;

      positions[i * 3]     = Math.cos(angle) * radius;
      positions[i * 3 + 1] = Math.sin(angle) * radius;
      positions[i * 3 + 2] = z;

      sizes[i]  = 0.6 + Math.random() * 1.8;
      depths[i] = (z + depth / 2) / depth; // normalise 0→1
    }
    return { positions, sizes, depths };
  }, [count]);

  useFrame((state, delta) => {
    timeRef.current += delta;
    if (meshRef.current)  meshRef.current.rotation.z += delta * 0.04;
    if (matRef.current)   matRef.current.uniforms.uTime.value = timeRef.current;
  });

  return (
    <points ref={meshRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" count={count} array={positions} itemSize={3} />
        <bufferAttribute attach="attributes-aSize"    count={count} array={sizes}     itemSize={1} />
        <bufferAttribute attach="attributes-aDepth"   count={count} array={depths}    itemSize={1} />
      </bufferGeometry>
      <shaderMaterial
        ref={matRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={{ uTime: { value: 0 } }}
        transparent
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

import { useState, useEffect, useRef } from 'react';

export default function ResumeModal({ isOpen, onClose }) {
  const modalRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [isOpen]);

  useEffect(() => {
    const handleKey = (e) => { if (e.key === 'Escape') onClose(); };
    if (isOpen) document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="resume-modal-backdrop"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
      role="dialog"
      aria-modal="true"
      aria-label="Resume viewer"
    >
      <div className="resume-modal-card" ref={modalRef}>
        <div className="resume-modal-header">
          <div>
            <h2 style={{ fontSize: '1.2rem', fontWeight: 700, color: '#fff' }}>
              My Resume: <span style={{ color: 'var(--accent)' }}>On Paper!</span>
            </h2>
          </div>
          <button
            className="resume-modal-close"
            onClick={onClose}
            aria-label="Close resume modal"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        </div>
        <div className="resume-modal-body">
          <iframe
            src="/resume.pdf"
            title="Aizaz Noor Resume"
            width="100%"
            height="100%"
            style={{ border: 'none', borderRadius: '12px' }}
          />
        </div>
        <div className="resume-modal-footer">
          <a
            href="/resume.pdf"
            download="Aizaz_Noor_Resume.pdf"
            className="btn btn-primary"
            style={{ fontSize: '0.85rem', padding: '10px 24px' }}
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" /><polyline points="7 10 12 15 17 10" /><line x1="12" y1="15" x2="12" y2="3" />
            </svg>
            Download PDF
          </a>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import MagneticButton from '../components/MagneticButton';

export default function Contact() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [submitError, setSubmitError] = useState(null);
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name } = e.target;
    setSubmitError(null);
    setErrors(prev => {
      if (!prev[name]) return prev;
      const newErrors = { ...prev };
      delete newErrors[name];
      return newErrors;
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const form = e.target;
    const formData = new FormData(form);
    
    // Inject access_key from env or default fallback
    const accessKey = import.meta.env.VITE_WEB3FORMS_ACCESS_KEY || "e7f3a8dd-fb55-4527-9641-6b23afd91138";
    formData.set('access_key', accessKey);
    
    const newErrors = {};
    const emailStr = formData.get('email');
    if (!formData.get('name')) newErrors.name = 'Required';
    
    if (!emailStr) {
      newErrors.email = 'Required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailStr)) {
      newErrors.email = 'Invalid email address';
    }

    if (!formData.get('subject')) newErrors.subject = 'Required';
    if (!formData.get('message')) newErrors.message = 'Required';
    
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    
    setErrors({});
    setSubmitError(null);
    setIsSubmitting(true);
    
    try {
      const object = Object.fromEntries(formData);
      const json = JSON.stringify(object);
      
      const response = await fetch("https://api.web3forms.com/submit", {
        method: 'POST',
        body: json,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      });
      
      if (response.ok) {
        setIsSuccess(true);
        form.reset();
        setTimeout(() => setIsSuccess(false), 5000);
      } else {
        setSubmitError("Failed to deliver message. Please reach out directly via email.");
      }
    } catch (error) {
      setSubmitError("Network error. Please try again or email directly.");
    } finally {
