import React, { Suspense, useEffect, useRef, useMemo, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Stars } from '@react-three/drei';
import ParticleTunnel from './ParticleTunnel';

function CameraRig({ isReducedMotion }) {
  const maxScroll = useRef(0);
  const frameCount = useRef(0);

  useEffect(() => {
    const updateMaxScroll = () => {
      maxScroll.current = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
    };

    updateMaxScroll();

    const resizeObserver = new ResizeObserver(updateMaxScroll);
    resizeObserver.observe(document.body);

    return () => resizeObserver.disconnect();
  }, []);

  useFrame((state) => {
    if (document.hidden || isReducedMotion) return;

    // Throttle to every 2nd frame on mobile to reduce GPU load
    frameCount.current++;
    const isMobile = window.innerWidth < 768;
    if (isMobile && frameCount.current % 2 !== 0) return;

    const scrollProgress = maxScroll.current > 0 ? window.scrollY / maxScroll.current : 0;
    const startZ = 150;
    const endZ = -100;
    const targetZ = startZ + scrollProgress * (endZ - startZ);
    // Smooth dampening
    state.camera.position.z += (targetZ - state.camera.position.z) * 0.05;

    // VisionOS-style subtle mouse parallax on desktop
    if (!isMobile) {
      const targetRotY = state.pointer.x * 0.06;
      const targetRotX = -state.pointer.y * 0.06;
      state.camera.rotation.y += (targetRotY - state.camera.rotation.y) * 0.05;
      state.camera.rotation.x += (targetRotX - state.camera.rotation.x) * 0.05;
    }
  });
  return null;
}

export default function Background3D() {
  const isMobile = useMemo(() => typeof window !== 'undefined' && window.innerWidth < 768, []);
  const [isReducedMotion, setIsReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setIsReducedMotion(mediaQuery.matches);
    const listener = (e) => setIsReducedMotion(e.matches);
    mediaQuery.addEventListener('change', listener);
    return () => mediaQuery.removeEventListener('change', listener);
  }, []);

  // Pause the canvas loop when the page is not visible
  const canvasRef = useRef(null);
  useEffect(() => {
    const handleVisibility = () => {
      if (canvasRef.current) {
        canvasRef.current.style.visibility = document.hidden ? 'hidden' : 'visible';
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);
    return () => document.removeEventListener('visibilitychange', handleVisibility);
  }, []);

  if (isReducedMotion) {
    return (
      <div
        style={{
          position: 'fixed',
          inset: 0,
          width: '100vw',
          height: '100vh',
          zIndex: 0,
          background: '#050507',
          pointerEvents: 'none'
        }}
      />
    );
  }

  return (
    <div
      ref={canvasRef}
      style={{ position: 'fixed', inset: 0, width: '100vw', height: '100vh', zIndex: 0, pointerEvents: 'none' }}
    >
      <Canvas
        dpr={[1, isMobile ? 1 : 1.5]}
        camera={{ position: [0, 0, 150], fov: 70, near: 0.1, far: 1000 }}
        gl={{ antialias: false, alpha: false, powerPreference: 'high-performance' }}
        frameloop="always"
      >
        <color attach="background" args={['#050507']} />
        <ambientLight intensity={0.15} color="#ffffff" />
        <Suspense fallback={null}>
          <Stars radius={200} depth={60} count={isMobile ? 400 : 900} factor={3} saturation={0} fade speed={0.2} />
          <ParticleTunnel count={isMobile ? 300 : 600} />
          <CameraRig isReducedMotion={isReducedMotion} />
        </Suspense>
      </Canvas>
    </div>
  );
}

import React from 'react';

export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI.
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // You can also log the error to an error reporting service here
    console.error("ErrorBoundary caught an error:", error, errorInfo);
    this.setState({ error, errorInfo });
  }

  render() {
    if (this.state.hasError) {
      // You can render any custom fallback UI
      return (
        <div style={{
          height: '100vh', width: '100vw', display: 'flex',
          flexDirection: 'column', justifyContent: 'center', alignItems: 'center',
          backgroundColor: '#020205', color: 'white', padding: '2rem', textAlign: 'center'
        }}>
          <h1 style={{ color: '#ec4899', marginBottom: '1rem' }}>Something went wrong.</h1>
          <p style={{ color: '#a8a8b3', marginBottom: '2rem', maxWidth: '600px' }}>
            The 3D scene encountered an error. This is usually due to a missing asset or a WebGL issue.
          </p>
          <button 
            onClick={() => window.location.reload()}
            style={{
              padding: '8px 16px', backgroundColor: '#00f0ff', color: 'black',
              border: 'none', borderRadius: '5px', fontWeight: 'bold', cursor: 'pointer'
            }}
          >
            Reload Page
          </button>
          {this.state.error && (
            <pre style={{ 
              marginTop: '2rem', padding: '1rem', background: 'rgba(255,255,255,0.1)', 
              borderRadius: '8px', maxWidth: '80%', overflowX: 'auto', textAlign: 'left',
              fontSize: '12px', color: '#ff8888'
            }}>
              {this.state.error.toString()}
            </pre>
          )}
        </div>
      );
    }

    return this.props.children; 
  }
}

import React, { useState, useEffect } from 'react';

export default React.memo(function GithubStats() {
  const [stats, setStats] = useState({ repos: 15, stars: 15, forks: 1 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchStats() {
      const CACHE_KEY = 'gh_stats_cache_v1';
      const CACHE_TTL = 3600000; // 1 hour

      try {
        const cached = localStorage.getItem(CACHE_KEY);
        if (cached) {
          const parsed = JSON.parse(cached);
          if (Date.now() - parsed.timestamp < CACHE_TTL) {
            setStats(parsed.data);
            setLoading(false);
            return;
          }
        }
      } catch (e) {
        // Fallthrough if localStorage is restricted
      }

      try {
        const [userRes, reposRes] = await Promise.all([
          fetch('https://api.github.com/users/Aizaz-Noor'),
          fetch('https://api.github.com/users/Aizaz-Noor/repos?per_page=100')
        ]);

        if (!userRes.ok) throw new Error('Failed to fetch user');
        if (!reposRes.ok) throw new Error('Failed to fetch repos');

        const [userData, reposData] = await Promise.all([
          userRes.json(),
          reposRes.json()
        ]);

        let totalStars = 0;
        let totalForks = 0;

        for (const repo of reposData) {
          totalStars += repo.stargazers_count || 0;
          totalForks += repo.forks_count || 0;
        }

        const freshStats = {
          repos: userData.public_repos || 15,
          stars: totalStars,
          forks: totalForks,
        };

        setStats(freshStats);
        try {
          localStorage.setItem(CACHE_KEY, JSON.stringify({
            timestamp: Date.now(),
            data: freshStats,
          }));
        } catch (e) {}
      } catch (error) {
        console.error("Error fetching GitHub stats:", error);
      } finally {
        setLoading(false);
      }
    }

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div style={{ display: 'flex', gap: '2rem', flexWrap: 'wrap', opacity: 0.5, justifyContent: 'center' }}>
        <div>
          <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>...</div>
          <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Repositories</div>
        </div>
        <div>
          <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>...</div>
          <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Stars</div>
        </div>
        <div>
          <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>...</div>
          <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Forks</div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', gap: '2rem', flexWrap: 'wrap', justifyContent: 'center' }}>
      <div>
        <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>{stats.repos}</div>
        <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Repositories</div>
      </div>
      <div>
        <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>{stats.stars}</div>
        <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Stars</div>
      </div>
      <div>
        <div style={{ fontSize: '2rem', fontWeight: 700, color: 'var(--text-1)', fontFamily: 'monospace' }}>{stats.forks}</div>
        <div style={{ fontSize: '0.85rem', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Forks</div>
      </div>
    </div>
  );
});

