const ProjectCard = React.memo(function ProjectCard({ project }) {
  const cardRef = React.useRef(null);

  const handleMouseMove = React.useCallback((e) => {
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    cardRef.current.style.setProperty('--mx', `${e.clientX - rect.left}px`);
    cardRef.current.style.setProperty('--my', `${e.clientY - rect.top}px`);
  }, []);

  return (
    <TiltCard style={{ height: '100%' }}>
      <div
        ref={cardRef}
        className="glass-panel project-card"
        onMouseMove={handleMouseMove}
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
        }}
      >
        {/* Number */}
        <div
          className="g-text"
          style={{
            fontSize: '0.65rem',
            fontWeight: 700,
            letterSpacing: '0.2em',
            marginBottom: '1rem',
            fontFamily: 'monospace',
          }}
        >
          {project.num}
        </div>

        {/* Name */}
        <h3 style={{
          fontFamily: 'inherit',
          fontSize: '1.05rem',
          fontWeight: 700,
          color: 'var(--text-1)',
          letterSpacing: '-0.01em',
          marginBottom: '0.75rem',
        }}>
          {project.name}
        </h3>

        {/* Desc */}
        <p style={{ fontSize: '0.85rem', lineHeight: 1.65, marginBottom: '1rem', color: 'var(--text-2)' }}>
          {project.desc}
        </p>

        {/* Tags */}
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '1.5rem', flexGrow: 1, alignContent: 'flex-start' }}>
          {project.tags.map((t) => (
            <span key={t} className="tag">{t}</span>
          ))}
        </div>

        {/* Architecture Diagram */}
        {project.diagram && (
          <div style={{ marginBottom: '1.5rem' }}>
            {project.diagram}
          </div>
        )}

        {/* Links */}
        <div style={{ marginTop: 'auto', display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <a href={project.url} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()} className="project-link-text" style={{
            fontSize: '0.8rem',
            letterSpacing: '0.04em',
            fontWeight: 500,
            display: 'inline-flex',
            alignItems: 'center',
            gap: '6px',
            color: 'var(--text-1)',
            textDecoration: 'none',
          }}>
            View on GitHub
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/>
            </svg>
          </a>
          {project.demoUrl && project.demoUrl !== '#' && (
            <a href={project.demoUrl} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()} className="project-link-text g-text" style={{
              fontSize: '0.8rem',
              letterSpacing: '0.04em',
              fontWeight: 500,
              display: 'inline-flex',
              alignItems: 'center',
              gap: '6px',
            }}>
              Live Demo
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line>
